#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf_t {
    uint32_t *data;
    size_t head;   /* index of oldest element */
    size_t tail;   /* next free slot for push */
    size_t count;  /* current number of elements */
    size_t capacity;
};

ringbuf_t *ringbuf_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->data = calloc(capacity, sizeof(uint32_t));
    if (!rb->data) {
        free(rb);
        return NULL;
    }

    rb->head  = 0;
    rb->tail  = 0;
    rb->count = 0;
    rb->capacity = capacity;
    return rb;
}

void ringbuf_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->data);
    free(rb);
}

int ringbuf_push(ringbuf_t *rb, uint32_t item)
{
    if (!rb)
        return 0;

    /* If full, overwrite oldest */
    if (rb->count == rb->capacity) {
        rb->data[rb->tail] = item;
        rb->head = (rb->head + 1) % rb->capacity;
        /* tail doesn't change — it slots over the old head value */
    } else {
        rb->data[rb->tail] = item;
        rb->tail = (rb->tail + 1) % rb->capacity;
        rb->count++;
    }
    return 1;
}

int ringbuf_pop(ringbuf_t *rb, uint32_t *out_item)
{
    if (!rb || rb->count == 0)
        return 0;

    if (out_item)
        *out_item = rb->data[rb->head];

    rb->head = (rb->head + 1) % rb->capacity;
    rb->count--;
    return 1;
}

int ringbuf_peek(const ringbuf_t *rb, int index, uint32_t *out_item)
{
    if (!rb || index < 0 || (size_t)index >= rb->count)
        return 0;

    int real_idx = (rb->head + index) % rb->capacity;
    if (out_item)
        *out_item = rb->data[real_idx];
    return 1;
}

size_t ringbuf_count(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

int ringbuf_is_full(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return (int)(rb->count == rb->capacity);
}

int ringbuf_is_empty(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return (int)(rb->count == 0);
}

size_t ringbuf_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "ringbuf.h"

static int passed = 0;
static int failed = 0;
#define TEST(name) static void name(void)
#define RUN(name) do { printf("  %-45s", #name); name(); } while(0)
#define ASSERT(cond) do { \
    if (!(cond)) { printf("FAIL (%s:%d): %s\n", __FILE__, __LINE__, #cond); failed++; return; } \
} while(0)
#define ASSERT_EQ(a,b) ASSERT((a) == (b))

/* 1. NULL safety */
TEST(null_safety)
{
    ASSERT(ringbuf_create(0) == NULL);
    ringbuf_destroy(NULL); /* should not crash */
    ASSERT(ringbuf_count(NULL) == 0);
    ASSERT(!ringbuf_is_full(NULL));
    ASSERT(!ringbuf_is_empty(NULL));
    ASSERT(ringbuf_capacity(NULL) == 0);
    /* peek/pop with NULL rb, empty pop */
    uint32_t tmp;
    ASSERT(!ringbuf_peek(NULL, 0, &tmp));
    ASSERT(!ringbuf_pop(NULL, &tmp));
}

/* 2. Create / destroy */
TEST(create_destroy)
{
    ringbuf_t *rb = ringbuf_create(4);
    ASSERT(rb != NULL);
    ASSERT(ringbuf_count(rb) == 0);
    ASSERT(ringbuf_is_empty(rb));
    ASSERT(!ringbuf_is_full(rb));
    ASSERT(ringbuf_capacity(rb) == 4);
    ringbuf_destroy(rb);
}

/* 3. Push / pop round-trip */
TEST(push_pop_roundtrip)
{
    ringbuf_t *rb = ringbuf_create(4);
    for (uint32_t i = 1; i <= 4; i++)
        ASSERT(ringbuf_push(rb, i));
    ASSERT(ringbuf_is_full(rb));
    ASSERT(ringbuf_count(rb) == 4);

    uint32_t vals[] = {0}; /* just to hold each pop */
    uint32_t expected = 1;
    for (int i = 0; i < 4; i++) {
        ASSERT(ringbuf_pop(rb, &vals[i]));
        ASSERT_EQ(vals[i], expected++);
    }
    ASSERT(ringbuf_is_empty(rb));
    ringbuf_destroy(rb);
}

/* 4. Overflow: oldest evicted */
TEST(overflow_discard)
{
    ringbuf_t *rb = ringbuf_create(3);

    /* Fill it up */
    ringbuf_push(rb, 10);
    ringbuf_push(rb, 20);
    ringbuf_push(rb, 30);
    ASSERT(ringbuf_is_full(rb));

    /* Pushing one more evicts head (10) */
    ringbuf_push(rb, 40);
    ASSERT(!ringbuf_is_empty(rb));
    ASSERT(ringbuf_count(rb) == 3);
    ASSERT(ringbuf_is_full(rb));

    /* Pop in order: should see 20, 30, 40 */
    uint32_t v;
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 20);
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 30);
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 40);
    ASSERT(ringbuf_is_empty(rb));

    ringbuf_destroy(rb);
}

/* 5. Peek */
TEST(peek)
{
    ringbuf_t *rb = ringbuf_create(5);
    ringbuf_push(rb, 100);
    ringbuf_push(rb, 200);
    uint32_t v;
    ASSERT(ringbuf_peek(rb, 0, &v)); ASSERT_EQ(v, 100);
    ASSERT(ringbuf_peek(rb, 1, &v)); ASSERT_EQ(v, 200);
    ASSERT(!ringbuf_peek(rb, 2, &v)); /* out of range */
    ASSERT(ringbuf_peek(rb, -1, &v) == 0);
    ringbuf_destroy(rb);
}

/* 6. Wrap-around with pop/push interleave — the tricky case */
TEST(wrap_interleaved)
{
    ringbuf_t *rb = ringbuf_create(3);

    /* Fill: [1,2,3], head=0, tail=0 (after wrap at index 3→0 overflow) */
    ringbuf_push(rb, 1);
    ringbuf_push(rb, 2);
    ringbuf_push(rb, 3);
    ASSERT(ringbuf_is_full(rb));

    /* Push 4: overflow → evict head(1), buffer becomes [2,3,x→4], head=1 */
    ringbuf_push(rb, 4);
    ASSERT(ringbuf_count(rb) == 3);

    /* Pop two: 2, 3. Buffer empty. tail = 0 now (after pop) */
    uint32_t v;
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 2);
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 3);
    ASSERT(ringbuf_is_empty(rb));

    /* Push one: slot 0. head moves to 1. */
    ringbuf_push(rb, 5);
    ASSERT(ringbuf_count(rb) == 1);

    /* Pop it */
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 5);
    ASSERT(ringbuf_is_empty(rb));

    ringbuf_destroy(rb);
}

/* 7. Pop from empty returns 0 */
TEST(pop_empty)
{
    ringbuf_t *rb = ringbuf_create(2);
    uint32_t v;
    ASSERT(!ringbuf_pop(rb, &v));
    ringbuf_destroy(rb);
}

int main(void)
{
    printf("ringbuf tests:\n");
    RUN(null_safety);             printf("PASS\n"); passed++;
    RUN(create_destroy);          printf("PASS\n"); passed++;
    RUN(push_pop_roundtrip);      printf("PASS\n"); passed++;
    RUN(overflow_discard);        printf("PASS\n"); passed++;
    RUN(peek);                    printf("PASS\n"); passed++;
    RUN(wrap_interleaved);        printf("PASS\n"); passed++;
    RUN(pop_empty);               printf("PASS\n"); passed++;

    printf("\n%d passed, %d failed\n", passed, failed);
    return failed > 0 ? 1 : 0;
}

