{
    ringbuf_t *rb = ringbuf_create(2);
    for (uint32_t i = 0; i < 100; i++) {
        ringbuf_push(rb, i + 1);
    }
    // only last 2 remain: 99, 100
    uint32_t v;
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 99u);
    ringbuf_pop(rb, &v); ASSERT_EQ(v, 100u);
    ASSERT(ringbuf_is_empty(rb));
    ringbuf_destroy(rb);
}

